import{_ as e,c as a,a2 as p,o}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"第一百五十四章 丰厚供养的祸害","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/154第一百五十四章 丰厚供养的祸害.md","filePath":"meditation/巴利文大藏经/154第一百五十四章 丰厚供养的祸害.md"}'),_={name:"meditation/巴利文大藏经/154第一百五十四章 丰厚供养的祸害.md"};function r(n,t,i,s,d,c){return o(),a("div",null,t[0]||(t[0]=[p('<h1 id="第一百五十四章-丰厚供养的祸害" tabindex="-1">第一百五十四章 丰厚供养的祸害 <a class="header-anchor" href="#第一百五十四章-丰厚供养的祸害" aria-label="Permalink to &quot;第一百五十四章 丰厚供养的祸害&quot;">​</a></h1><p>完全读懂巴利文大藏经</p><p>相应部16相应8经/教诫经第三(迦叶相应/因缘篇/如来记说)</p><p>有个时候，佛陀住在舍卫城的栗鼠饲养处，有一天，佛陀正在为出家弟子们说法，这时，迦叶尊者来到佛陀的住处，顶礼佛陀后，迦叶尊者就在一旁坐下，佛陀对迦叶尊者说：“迦叶！你来为比丘们（出家人），说一些法，就像如来对他们说法一样。”</p><p>迦叶尊者说：“世尊，诸位学友，过去有一些长老比丘（出家人），他们是远离人群，是在深山密林中修行的人，他们也称赞那些远离人群，在深山密林中修行的人；他们是中午的时候挨家挨户，不分贫富贵贱家庭化缘饭食的出家人，他们也称赞那些在中午前挨家挨户，不分贫富贵贱家庭化缘饭食的出家人；他们穿的是别人遗弃不要的衣服、布料裁剪而成的衣服，他们也称赞那些穿别人遗弃不要的衣服、布料裁剪而成衣服的出家人；他们是只有三件法衣的出家人，他们也称赞那些只有三件法衣的出家人；他们是欲望很少的人，他们也称赞那些欲望很少的人；他们是知足的人，他们也称赞那些知足的人；他们是独自一人修行的人，他们也称赞那些独自一人修行的人；他们是远离人际交往的人，他们也称赞那些远离人际交往的人；他们是精进修行的人，他们也称赞那些精进修行的人。</p><p>世尊，诸位学友，当过去的这些长老比丘听说现在还有一些比丘在效法他们，在学习他们，在用与他们相同的方法修行，这些长老比丘就会邀请这些比丘到他们那里去，长老比丘会询问这些比丘的名字，以及他们修行时的体悟，询问他们修行时遇见的困难和问题。长老比丘明白了这些比丘修行的具体情况后，就会以自己真实的修行实践来教导这些比丘，为他们解决修行中遇见的各种困难和问题，与这些比丘分享自己多年来修行的实践经验，以及提醒这些比丘修行到各个阶段需要注意的问题，避免他们在错误的修行方法和境界上驻留，纠正他们错误的修行方法，除灭他们对各种修行境界的贪爱、留恋。这样这些比丘就会因为受到长老比丘的教导而获得长久的功德利益，让他们自己的内心长久的保持清净，让他们能够尽快的除灭一切的烦恼和痛苦，从而从生死轮回中永远的解脱出来，最终让他们达到不生不灭涅槃的境界。</p><p>世尊，诸位学友，过去有一些有名气的长老比丘（出家人），他们不远离人群，他们不是在深山密林中修行的人，他们住在华丽的房屋内，他们也不称赞那些远离人群，在深山密林中修行的人；他们不是中午的时候挨家挨户，不分贫富贵贱家庭化缘饭食的出家人，他们足不出户，他们在华丽的房屋内接受世间人的供养，他们也不称赞那些在中午前挨家挨户，不分贫富贵贱家庭化缘饭食的出家人；他们穿的不是别人遗弃不要的衣服、布料裁剪而成的衣服，他们穿的是漂亮崭新的衣服，他们也不称赞那些穿别人遗弃不要的衣服、布料裁剪而成衣服的出家人；他们不是只有三件法衣的出家人，他们拥有非常多的法衣，甚至于法衣数量多的，连他们自己都记不清楚到底有多少件，他们也不称赞那些只有三件法衣的出家人；他们本来应该是欲望很少的人，可是他们却会为争抢世间人的供养而互相指责、诽谤、愤怒、悲伤，他们不仅不会称赞那些欲望很少的人，还会嘲讽这些欲望少的出家人没有本事无法获得更多的供养；他们是贪得无厌的人，他们不称赞那些知足的人，他们轻视、瞧不起那些知足的人，甚至于还会认为这些人是愚蠢的人；他们不是独自一人修行的人，他们的周围有很多人，这些在他们身边的人不会指出他们修行的错误，只会称赞他们，只会赞叹他们，他们不会称赞那些独自一人修行的人，他们认为这些人都是傻子；他们不是远离人际交往的人，他们每天都会接见无数多的人，他们会根据世间人供养物品价值的高低，选择性的为这些人说法，如果世间人没有供养给他们物品，或者供养的物品达不到他们心中要求的时候，他们就会愤怒的离开，他们不会称赞那些远离人际交往的人；他们不是精进修行的人，他们错误的认为所谓的精进修行就是通过说法获得更多的供养。他们也不称赞那些精进修行的人，他们会认为这些人是愚蠢的傻子。</p><p>世尊，诸位学友，当过去的这些有名气的长老比丘听说现在还有一些比丘在效法他们，在学习他们，在用与他们相同的方法修行，这些长老比丘就会邀请这些比丘到他们那里去，长老比丘会询问这些比丘的名字，他们不会询问这些比丘修行时的体悟，不会询问这些比丘修行时遇见的困难和问题。这些长老比丘只会询问这些比丘获得世间人供养的情况，以及这些比丘所住房屋的华丽程度，他们会象征性的互相讲一些佛法，证明自己还是世尊的弟子，可是他们却不会深入的去修习如来的正法，不会实践的去修行如来的正法，这些长老比丘会根据这些比丘供养给他们物品价值的高低，或者他们从这些比丘处获得好处的多少，来传授给这些比丘如何获得世间人更多的供养，如何住进更华丽的房屋，如何说法得到世间人的信任，并让世间人心甘情愿的拿出贵重的物品供养自己。这样这些比丘就会因为受到长老比丘错误的教导而失去本来清净的境界，他们无法获得丝毫的功德利益，他们将会为了获得世间人的供养而胡思乱想、胡作非为。他们将会被世间人的供养束缚捆绑，他们将会产生无穷无尽的贪欲，他们将会由此产生无数多的烦恼和痛苦，他们死后将会投生到痛苦的地方，投生到贫贱的地方，甚至于投生到地狱、饿鬼、畜生三恶道受苦，他们离如来的正法越来越远，对于指出他们问题的人，他们会百般抵赖，不肯承认自己犯下的错误，并恶口回应、诅咒揭露他们错误、恶行的人会由此堕落到地狱、饿鬼、地狱三恶道里面去。他们不接受任何人的监督，不接受任何人正确的见解。本来他们出家的目的是为了除灭对世间一切事物的束缚和捆绑，是为了除灭他们自己的一切烦恼和痛苦，然而他们却被世间人的供养所污染，所束缚捆绑，沉溺在贪欲的海洋中无法解脱出来。</p><p>世尊，诸位学友，我就说这样的长老比丘，这样的出家人他们就是：「出家后被世间丰厚供养、舒适生活祸害的人，他们出家的目的本来是为了解除世间一切事物对自己的束缚和捆绑，本来是为了除灭一切的烦恼和痛苦，本来是为了从生死轮回中永远的解脱出来，本来是为了最终达到不生不灭涅槃的境界，可是他们出家后却为了获得各种供养、舒适生活而迷失在贪欲的森林中，无法找到出路。他们就是出家修行被供养、舒适生活祸害的人，他们就是被贪欲祸害的出家人。」”</p><p>佛陀和迦叶尊者说法后，听法的出家弟子们都再次的顶礼佛陀和迦叶尊者，随喜赞叹佛陀和迦叶尊者说法的无量功德，他们都按着佛陀和迦叶尊者所说的法去修行。</p>',10)]))}const f=e(_,[["render",r]]);export{m as __pageData,f as default};
